    "trim": true,
    "caseSensitive": true,
    "settlementDuplicates": "reject",
    "tolerance": "0.00"
  },
  "template": {
    "path": "",
    "sheet": "",
    "startRow": 6,
    "endRow": 35,
    "columns": {
      "key": "A",
      "label": "B",
      "expected": "C",
      "actual": "D",
      "difference": "E",
      "status": "F"
    }
  }
}
